	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}

	// dp[i][j] = true if a[i..j] can be partitioned into an odd number of valid subsegments
	// We'll use a 2D array of maps: dp[i][j][parity] where parity is 0 (even) or 1 (odd)
	// But since n is small (<=100), we can use a 3D array
	// dp[i][j][p] = true if a[i..j] can be partitioned into p (mod 2) valid subsegments
	// p=1 means odd count, p=0 means even count
	// We want dp[0][n-1][1] = true

	// Initialize dp
	dp := make([][][]bool, n)
	for i := range dp {
		dp[i] = make([][]bool, n)
		for j := range dp[i] {
			dp[i][j] = make([]bool, 2)
		}
	}

	// Base case: single element
	for i := 0; i < n; i++ {
		if a[i]%2 == 1 {
			dp[i][i][1] = true // 1 subsegment (odd count)
		}
	}

	// Fill dp for lengths > 1
	for length := 2; length <= n; length++ {
		for i := 0; i+length-1 < n; i++ {
			j := i + length - 1
			// Check if a[i..j] itself is a valid subsegment (odd length, starts and ends with odd)
			if length%2 == 1 && a[i]%2 == 1 && a[j]%2 == 1 {
				dp[i][j][1] = true
			}
			// Try all possible splits
			for k := i; k < j; k++ {
				// Split into a[i..k] and a[k+1..j]
				for p1 := 0; p1 < 2; p1++ {
					for p2 := 0; p2 < 2; p2++ {
						if dp[i][k][p1] && dp[k+1][j][p2] {
							dp[i][j][(p1+p2)%2] = true
						}
					}
				}
			}
		}
	}

	if dp[0][n-1][1] {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
