	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
	}

	// dp[i][j][p] = can we partition a[i..j] into p (mod 2) subsegments satisfying conditions
	// p: 0 means even count, 1 means odd count
	// We'll use 3D memo: dp[i][j][p]
	// But to keep it simple, let's do recursive with memo.

	memo := make([][][]int, n)
	for i := range memo {
		memo[i] = make([][]int, n)
		for j := range memo[i] {
			memo[i][j] = make([]int, 2)
			memo[i][j][0] = -1
			memo[i][j][1] = -1
		}
	}

	var solve func(i, j, p int) bool
	solve = func(i, j, p int) bool {
		if i > j {
			return p == 0
		}
		if memo[i][j][p] != -1 {
			return memo[i][j][p] == 1
		}
		res := false
		// Try all possible first subsegments starting at i
		for k := i; k <= j; k++ {
			// Subsegment a[i..k] must have odd length, start and end with odd
			length := k - i + 1
			if length%2 == 1 && a[i]%2 == 1 && a[k]%2 == 1 {
				// This subsegment is valid. Now partition the rest a[k+1..j] into (p-1) mod 2 subsegments
				if solve(k+1, j, (p-1+2)%2) {
					res = true
					break
				}
			}
		}
		if res {
			memo[i][j][p] = 1
		} else {
			memo[i][j][p] = 0
		}
		return res
	}

	// We want to partition the whole array into an odd number of valid subsegments
	if solve(0, n-1, 1) {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
