package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
	}

	// dp[i] = set of possible parity counts (0=even,1=odd) of valid partitions for prefix of length i
	dp := make([]map[int]bool, n+1)
	for i := range dp {
		dp[i] = make(map[int]bool)
	}
	dp[0][0] = true

	for i := 0; i < n; i++ {
		for j := i; j < n; j++ {
			// subsegment a[i..j]
			if a[i]%2 == 1 && a[j]%2 == 1 && (j-i+1)%2 == 1 {
				for prev := range dp[i] {
					dp[j+1][(prev+1)%2] = true
				}
			}
		}
	}

	if dp[n][1] {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
